import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_TRAYECTO, MODELO_ESTACION, TABLA_TRAYECTOS } from '../../models/estacion-trayecto.model.mjs';

export async function crearTrayectoRepository(trayecto) {
  await MODELO_TRAYECTO.build(PutItemCommand)
    .item(trayecto)
    .options({ condition: { attr: 'trayectoId', exists: false } })
    .send();
}

export async function listarTrayectosRepository() {
  const { Items = [] } = await TABLA_TRAYECTOS.build(ScanCommand)
    .entities(MODELO_TRAYECTO)
    .options({ consistent: true })
    .send();
  return Items;
}

