import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_TRAYECTO, MODELO_ESTACION, TABLA_TRAYECTOS } from '../../models/estacion-trayecto.model.mjs';

export async function buscarEstacionRepository(estacionId) {
  const { Item } = await MODELO_ESTACION.build(GetItemCommand)
    .key({ estacionId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarEstacionRepository(estacionId, minimo) {
  const { Items = [] } = await TABLA_TRAYECTOS.build(QueryCommand)
    .entities(MODELO_TRAYECTO)
    .query({ index: 'PorEstacion', partition: estacionId })
    .options({ filters: { Trayecto: { attr: 'distanciaKm', gte: minimo } } })
    .send();
  return Items;
}

import { trasladarTrayectoService } from './service.mjs';

export async function handler(event) {
  const trayectoId = Number(event.pathParameters.trayectoId);
  const { estacionId } = JSON.parse(event.body);
  const resultado = await trasladarTrayectoService(trayectoId, estacionId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarTrayectoRepository } from './repository.mjs';
import { buscarEstacionRepository } from '../../estaciones/consultar/repository.mjs';

export async function trasladarTrayectoService(trayectoId, estacionId) {
  const estacion = await buscarEstacionRepository(estacionId);
  if (!estacion) throw new Error('Estacion no encontrado');
  return trasladarTrayectoRepository(trayectoId, estacionId);
}

import { UpdateItemCommand } from 'dynamodb-toolbox/entity/actions/update';
import { MODELO_TRAYECTO, MODELO_ESTACION, TABLA_TRAYECTOS } from '../../models/estacion-trayecto.model.mjs';

export async function trasladarTrayectoRepository(trayectoId, estacionId) {
  const { Attributes } = await MODELO_TRAYECTO.build(UpdateItemCommand)
    .item({ trayectoId, estacionId })
    .options({
      condition: { attr: 'trayectoId', exists: true },
      returnValues: 'ALL_NEW'
    })
    .send();
  return Attributes;
}

import { consultarEstacionService } from './service.mjs';

export async function handler(event) {
  const estacionId = Number(event.pathParameters.estacionId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarEstacionService(estacionId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarEstacionRepository, consultarEstacionRepository } from './repository.mjs';

export async function consultarEstacionService(estacionId, minimo) {
  const estacion = await buscarEstacionRepository(estacionId);
  if (!estacion) throw new Error('Estacion no encontrado');
  const trayectos = await consultarEstacionRepository(estacionId, minimo);
  return { estacion, trayectos };
}

